source='''def transform(grid):
    """Connect aligned cells containing matching markers; intersections mix to 6."""
    h, w = len(grid), len(grid[0])
    row_cuts = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_cuts = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rb = [-1] + row_cuts + [h]
    cb = [-1] + col_cuts + [w]
    rows = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cols = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    nr, nc = len(rows), len(cols)
    cells = [[0] * nc for _ in range(nr)]
    for ri, (ra, rz) in enumerate(rows):
        for ci, (ca, cz) in enumerate(cols):
            colors = {grid[r][c] for r in range(ra, rz) for c in range(ca, cz) if grid[r][c] not in (0, 8)}
            if colors:
                cells[ri][ci] = next(iter(colors))
    covered = {2: set(), 3: set()}
    for color in (2, 3):
        pts = [(r, c) for r in range(nr) for c in range(nc) if cells[r][c] == color]
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                if r1 == r2:
                    covered[color].update((r1, c) for c in range(min(c1, c2), max(c1, c2) + 1))
                elif c1 == c2:
                    covered[color].update((r, c1) for r in range(min(r1, r2), max(r1, r2) + 1))
    out = [row[:] for row in grid]
    for ri, (ra, rz) in enumerate(rows):
        for ci, (ca, cz) in enumerate(cols):
            has2 = (ri, ci) in covered[2]
            has3 = (ri, ci) in covered[3]
            color = 6 if has2 and has3 else 2 if has2 else 3 if has3 else 0
            if color:
                for r in range(ra, rz):
                    for c in range(ca, cz):
                        out[r][c] = color
    return out
